export function getCyberpunkMeta(card: { id?: string; card_number?: string }): CyberpunkCardMeta | null {
  if (card.id && CYBERPUNK_CARDS_BY_ID[card.id]) {
    return CYBERPUNK_CARDS_BY_ID[card.id];
  }
  if (card.card_number) {
    if (CYBERPUNK_CARDS_BY_NUMBER[card.card_number]) {
      return CYBERPUNK_CARDS_BY_NUMBER[card.card_number];
    }
    const lower = card.card_number.toLowerCase();
    if (CYBERPUNK_CARDS_BY_NUMBER[lower]) {
      return CYBERPUNK_CARDS_BY_NUMBER[lower];
    }
  }
  return null;
}
